///
/// Per CommonMark §4.5, backtick fences cannot have backtick characters in
/// their info string; such a line is parsed as a paragraph, not a code block.
///
/// Returns `Some(range)` covering the first stray backtick in the info string
/// when the current line opens with a backtick fence (```` ``` ````) whose
/// info string contains a backtick. Returns `None` for tilde fences, backtick
/// fences with a clean info string, and non-fence lines.
pub(crate) fn backtick_info_string_error(p: &mut MarkdownParser) -> Option<TextRange> {
    p.lookahead(|p| {
        p.skip_line_indent(MAX_BLOCK_PREFIX_INDENT);

        let fence_start: usize = p.cur_range().start().into();
        let rest = p.source_after_current();

        let (fence_char, fence_len) = detect_fence(rest)?;
        if fence_char != '`' {
            return None;
        }

        // The info string runs from just after the fence characters to the end
        // of the line.
        let after_fence = &rest[fence_len..];
        let info_string = after_fence
            .split_terminator(['\n', '\r'])
            .next()
            .unwrap_or(after_fence);

        // Byte offset (backticks are ASCII, so this is a valid char boundary).
        let offset = info_string.find('`')?;
        let backtick_pos = fence_start + fence_len + offset;

        let start = TextSize::from(backtick_pos as u32);
        Some(TextRange::new(start, start + TextSize::from(1u32)))
    })
}

